-- Banking Management System: generated data for 1,000 customers (seed 42).
-- Load after banking_schema.sql:  psql -d bank -v ON_ERROR_STOP=1 -f bank_data.sql
-- Rows: designation 11, customer_segment 10, currency 10, card_type 10, channel 10, transaction_type 14, loan_product 10, branch 26, employee 161, customer 1,000, kyc_document 1,448, account_type 10, account 1,189, account_holder 1,422, card_product 10, card 980, merchant 205, beneficiary 1,017, loan 72, bank_transaction 9,084
BEGIN;

-- designation: 11 rows

-- customer_segment: 10 rows

-- currency: 10 rows

-- card_type: 10 rows

-- channel: 10 rows

-- transaction_type: 14 rows

-- loan_product: 10 rows

-- branch: 26 rows

-- employee: 161 rows

UPDATE branch b SET manager_employee_id = e.employee_id
FROM employee e JOIN designation d ON d.designation_id = e.designation_id
WHERE d.title = 'Branch Manager' AND e.branch_id = b.branch_id;

-- customer: 1,000 rows

-- kyc_document: 1,448 rows

-- account_type: 10 rows

-- account: 1,189 rows

-- account_holder: 1,422 rows

-- card_product: 10 rows

-- card: 980 rows

-- merchant: 205 rows

-- beneficiary: 1,017 rows

-- loan: 72 rows

-- bank_transaction: 9,084 rows

-- Move each id counter past the rows inserted with explicit ids.
SELECT setval(pg_get_serial_sequence('designation', 'designation_id'), GREATEST(1, (SELECT max(designation_id) FROM designation)));
SELECT setval(pg_get_serial_sequence('customer_segment', 'segment_id'), GREATEST(1, (SELECT max(segment_id) FROM customer_segment)));
SELECT setval(pg_get_serial_sequence('currency', 'currency_id'), GREATEST(1, (SELECT max(currency_id) FROM currency)));
SELECT setval(pg_get_serial_sequence('card_type', 'card_type_id'), GREATEST(1, (SELECT max(card_type_id) FROM card_type)));
SELECT setval(pg_get_serial_sequence('channel', 'channel_id'), GREATEST(1, (SELECT max(channel_id) FROM channel)));
SELECT setval(pg_get_serial_sequence('transaction_type', 'txn_type_id'), GREATEST(1, (SELECT max(txn_type_id) FROM transaction_type)));
SELECT setval(pg_get_serial_sequence('loan_product', 'loan_product_id'), GREATEST(1, (SELECT max(loan_product_id) FROM loan_product)));
SELECT setval(pg_get_serial_sequence('branch', 'branch_id'), GREATEST(1, (SELECT max(branch_id) FROM branch)));
SELECT setval(pg_get_serial_sequence('employee', 'employee_id'), GREATEST(1, (SELECT max(employee_id) FROM employee)));
SELECT setval(pg_get_serial_sequence('customer', 'customer_id'), GREATEST(1, (SELECT max(customer_id) FROM customer)));
SELECT setval(pg_get_serial_sequence('kyc_document', 'document_id'), GREATEST(1, (SELECT max(document_id) FROM kyc_document)));
SELECT setval(pg_get_serial_sequence('account_type', 'account_type_id'), GREATEST(1, (SELECT max(account_type_id) FROM account_type)));
SELECT setval(pg_get_serial_sequence('account', 'account_id'), GREATEST(1, (SELECT max(account_id) FROM account)));
SELECT setval(pg_get_serial_sequence('account_holder', 'holder_id'), GREATEST(1, (SELECT max(holder_id) FROM account_holder)));
SELECT setval(pg_get_serial_sequence('card_product', 'card_product_id'), GREATEST(1, (SELECT max(card_product_id) FROM card_product)));
SELECT setval(pg_get_serial_sequence('card', 'card_id'), GREATEST(1, (SELECT max(card_id) FROM card)));
SELECT setval(pg_get_serial_sequence('merchant', 'merchant_id'), GREATEST(1, (SELECT max(merchant_id) FROM merchant)));
SELECT setval(pg_get_serial_sequence('beneficiary', 'beneficiary_id'), GREATEST(1, (SELECT max(beneficiary_id) FROM beneficiary)));
SELECT setval(pg_get_serial_sequence('loan', 'loan_id'), GREATEST(1, (SELECT max(loan_id) FROM loan)));
SELECT setval(pg_get_serial_sequence('bank_transaction', 'transaction_id'), GREATEST(1, (SELECT max(transaction_id) FROM bank_transaction)));

COMMIT;
ANALYZE;
